        for tc in obj["tool_calls"]:
            name = tc.get("name")
            tid = tc.get("id")
            args = tc.get("arguments")
            if not isinstance(args, str):
                args_raw = json.dumps(args, ensure_ascii=False, separators=(",", ":")) if args is not None else ""
                args_is_str = False
            else:
                args_raw = args
                args_is_str = True
            kind_ord[name] += 1
            ko = kind_ord[name]
            calls.append({
                "line_index": li,
                "tool_call_id": tid,
                "tool_kind": name,
                "kind_local_ordinal": ko,
                "transcript_ref": "transcript://019f830a-e078-7291-868d-63c406c499a4/%s/%d" % (name, ko),
                "arguments_json": args_raw,
                "arguments_is_string_in_transcript": args_is_str,
                "arguments_sha256": hashlib.sha256(args_raw.encode("utf-8")).hexdigest(),
                "arguments_byte_len": len(args_raw.encode("utf-8")),
