{"command":"$ids = @(
  '019f8322-0e29-7832-947c-35ba76d25653',
  '019f8322-0e28-7903-99da-a62b3313074a',
  '019f8322-0e29-7832-947c-35d7d61eec46',
  '019f8322-0e29-7832-947c-35c50405b5c6'
)
$root = 'C:\Users\phant\.grok\sessions\E%3A%5CAIdle_openworld'
foreach ($id in $ids) {
  $ch = "$root\$id\chat_history.jsonl"
  $lines = [System.IO.File]::ReadAllLines($ch)
  # find user directive line
  foreach ($L in $lines) {
    if ($L -match 'Directive 38' -or $L -match 'D2_manifestation_017.json' -or $L -match 'Exclusive write') {
      # extract key markers
      $markers = @()
      if ($L -match 'D2_manifestation_017') { $markers += 'lease_manif' }
      if ($L -match '\*\*manifestation\*\*') { $markers += 'title_manif' }
      if ($L -match '— \*\*manifestation\*\*') { $markers += 'emdash_manif' }
      if ($L -match 'P1 manifestation|manifestation correction') { $markers += 'manif_corr' }
      if ($L -match 'companion correction|\*\*companion\*\*') { $markers += 'comp' }
      if ($L -match '\*\*asset\*\*') { $markers += 'asset' }
      if ($L -match '\*\*persist\*\*') { $markers += 'persist' }
      if ($L -match 'original_d2_016_child_ref: `([^`]+)`') { $markers += "orig=$($Matches[1])" }
      Write-Output "ID=$id markers=$($markers -join ',')"
      # print a 300 char window around manifestation lease exclusivity
      $idx = $L.IndexOf('Exclusive')
      if ($idx -lt 0) { $idx = $L.IndexOf('D2_manifestation_017') }
      if ($idx -ge 0) {
        $start = [Math]::Max(0, $idx-80)
        Write-Output $L.Substring($start, [Math]::Min(500, $L.Length-$start))
      }
      break
    }
  }
}
","description":"Disambiguate correction child by exclusive lease"}

